"""Generate the normalized digital-twin metadata and private workshop migration."""
from pathlib import Path
sql=[]
def add(s):sql.append(s.strip()+'\n')
add('''create table public.asset_licenses(id text primary key,name text not null,url text,redistribution text not null check(redistribution in ('allowed','restricted','unknown')),attribution text not null,conditions text not null default '',evidence jsonb not null default '[]');
create table public.asset_sources(id text primary key,source_id text references public.sources,license_id text not null references public.asset_licenses,url text check(url is null or url like 'https://%'),author text not null,identity text not null,source_sha256 text check(source_sha256 is null or source_sha256 ~ '^[a-f0-9]{64}$'),evidence jsonb not null default '{}');
create table public.three_d_assets(id text primary key,source_id text not null references public.asset_sources,name text not null,kind text not null check(kind in ('visual-reference','nominal-cad','measured-cad','scan','reconstruction')),publication_status text not null default 'draft' check(publication_status in ('draft','published','withdrawn')),notes text not null default '',created_at timestamptz not null default now());
create table public.geometry_revisions(id text primary key,asset_id text not null references public.three_d_assets,revision integer not null check(revision>0),format text not null check(format in ('glb','gltf','obj','fbx','stl','step','ply','point-cloud','procedural')),runtime_path text check(runtime_path is null or runtime_path ~ '^/models/[A-Za-z0-9_./-]+[.]glb$'),source_units text not null check(source_units in ('m','mm','unknown')),meters_per_unit numeric check(meters_per_unit>0),source_sha256 text check(source_sha256 is null or source_sha256 ~ '^[a-f0-9]{64}$'),accuracy jsonb not null,statistics jsonb not null default '{}',known_gaps jsonb not null default '[]',created_at timestamptz not null default now(),unique(asset_id,revision));
create table public.digital_twin_vehicles(id text primary key,model_id text not null references public.vehicle_models,name text not null,source_id text references public.sources);
create table public.digital_twin_configurations(id text primary key,vehicle_id text not null references public.digital_twin_vehicles,name text not null,reference_year integer check(reference_year between 1987 and 1997),engine_family text not null,engine_variant text,body text,market text,production_date date,notes jsonb not null default '[]');
create table public.digital_twin_configuration_revisions(id text primary key,configuration_id text not null references public.digital_twin_configurations,revision text not null,graph_id text not null,graph jsonb not null check(octet_length(graph::text)<=2000000),publication_status text not null default 'draft' check(publication_status in ('draft','published','withdrawn')),created_at timestamptz not null default now(),unique(configuration_id,revision),unique(id,configuration_id));
create table public.assembly_nodes(configuration_revision_id text not null references public.digital_twin_configuration_revisions,id text not null,parent_id text,name text not null,part_id text references public.parts,geometry_revision_id text references public.geometry_revisions,transform jsonb not null,accuracy jsonb not null,source_ids text[] not null default '{}',guide_ids text[] not null default '{}',missing_evidence jsonb not null default '[]',primary key(configuration_revision_id,id),foreign key(configuration_revision_id,parent_id) references public.assembly_nodes(configuration_revision_id,id) deferrable initially deferred,check(parent_id is distinct from id));
create table public.component_meshes(id text primary key,geometry_revision_id text not null references public.geometry_revisions,part_id text references public.parts,mesh_name text not null,local_transform jsonb not null,evidence jsonb not null default '[]',association_status text not null check(association_status in ('illustrative','source-checked','verified','disputed')));''')
for table,columns in {
 'assembly_relationships':"from_node text not null,to_node text not null,kind text not null,reason text not null",
 'mounting_points':"node_id text not null,point jsonb,orientation jsonb,units text not null default 'unknown'",
 'fastener_connections':"from_node text not null,to_node text not null,part_id text references public.parts,quantity integer check(quantity>0),connection_points jsonb not null default '[]'",
 'electrical_connections':"from_node text not null,to_node text not null,connector_part_id text references public.parts,connection_points jsonb not null default '[]'",
 'fluid_connections':"from_node text not null,to_node text not null,fluid text not null,connection_points jsonb not null default '[]'",
 'disassembly_dependencies':"target_node text not null,prerequisite_node text not null,reason text not null,check(target_node<>prerequisite_node)",
 'removal_animations':"node_id text not null,kind text not null check(kind in ('documented','illustrative')),path jsonb not null,units text not null default 'unknown'",
 'repair_scene_steps':"guide_id text references public.guides,source_id text references public.sources,title text not null,node_ids text[] not null,required_removed text[] not null default '{}',step_index integer not null check(step_index>=0),check(guide_id is not null or source_id is not null)",
 'component_condition_examples':"part_id text references public.parts,geometry_revision_id text references public.geometry_revisions,condition text not null,caption text not null,reference_url text,check(part_id is not null or geometry_revision_id is not null)"
}.items():
 add(f"create table public.{table}(id text primary key,configuration_revision_id text not null references public.digital_twin_configuration_revisions,{columns},evidence jsonb not null default '[]',review_state text not null default 'missing' check(review_state in ('missing','illustrative','source-checked','verified','disputed')));")
 for field in ['from_node','to_node','node_id','target_node','prerequisite_node']:
  if field+' text' in columns:add(f'alter table public.{table} add foreign key(configuration_revision_id,{field}) references public.assembly_nodes(configuration_revision_id,id);')
add('''create table public.geometry_measurements(id text primary key,geometry_revision_id text not null references public.geometry_revisions,name text not null,value numeric not null,unit text not null,tolerance numeric check(tolerance>=0),method text not null,evidence jsonb not null,independent_check boolean not null default false,review_state text not null default 'missing' check(review_state in ('missing','illustrative','source-checked','verified','disputed')));
create table public.accuracy_reviews(id uuid primary key default gen_random_uuid(),geometry_revision_id text references public.geometry_revisions,configuration_revision_id text references public.digital_twin_configuration_revisions,axis text not null check(axis in ('visual','dimensions','alignment','mechanical','removal')),decision text not null check(decision in ('illustrative','source-checked','verified','disputed')),method text not null check(char_length(method)>=10),evidence jsonb not null check(jsonb_typeof(evidence)='array' and jsonb_array_length(evidence)>0),reviewer_id uuid default auth.uid() references auth.users on delete set null,reviewed_at timestamptz not null default now(),discrepancies text not null default '',check(num_nonnulls(geometry_revision_id,configuration_revision_id)=1));
create table public.reconstruction_jobs(id uuid primary key default gen_random_uuid(),user_id uuid not null default auth.uid() references auth.users on delete cascade,part_id text references public.parts,configuration_revision_id text references public.digital_twin_configuration_revisions,node_id text,method text not null check(method in ('licensed-cad','multiview','dimensioned-drawing','standard-parametric','manual-reconstruction')),status text not null default 'needs-evidence' check(status in ('needs-evidence','ready','processing','review','published','failed')),required_views jsonb not null default '[]',required_measurements jsonb not null default '[]',source_urls jsonb not null default '[]',notes text not null default '' check(char_length(notes)<=12000),created_at timestamptz not null default now(),unique(id,user_id),foreign key(configuration_revision_id,node_id) references public.assembly_nodes(configuration_revision_id,id),check(part_id is not null or node_id is not null));
create table public.reconstruction_evidence(id uuid primary key default gen_random_uuid(),job_id uuid not null,user_id uuid not null default auth.uid() references auth.users on delete cascade,source_url text not null check(source_url like 'https://%'),description text not null check(char_length(description) between 10 and 12000),rights_evidence text not null,created_at timestamptz not null default now(),foreign key(job_id,user_id) references public.reconstruction_jobs(id,user_id) on delete cascade);
create table public.user_workshop_sessions(id uuid primary key default gen_random_uuid(),user_id uuid not null default auth.uid() references auth.users on delete cascade,configuration_id text not null references public.digital_twin_configurations,configuration_revision_id text not null,label text not null check(char_length(label) between 1 and 100),state jsonb not null check(octet_length(state::text)<=500000),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),foreign key(configuration_revision_id,configuration_id) references public.digital_twin_configuration_revisions(id,configuration_id));''')
public_meta=['asset_licenses','asset_sources','digital_twin_vehicles','digital_twin_configurations']
root_assets=['three_d_assets']
revision_tables=['assembly_nodes','assembly_relationships','mounting_points','fastener_connections','electrical_connections','fluid_connections','disassembly_dependencies','removal_animations','repair_scene_steps','component_condition_examples']
geometry_tables=['component_meshes','geometry_measurements']
all_meta=public_meta+root_assets+['geometry_revisions','digital_twin_configuration_revisions']+revision_tables+geometry_tables+['accuracy_reviews']
for table in all_meta:
 add(f'alter table public.{table} enable row level security; revoke all on public.{table} from public,anon,authenticated; grant select on public.{table} to anon,authenticated; grant insert,update,delete on public.{table} to authenticated;')
 if table in public_meta:condition='true'
 elif table in root_assets or table=='digital_twin_configuration_revisions':condition="publication_status='published'"
 elif table=='geometry_revisions':condition='exists(select 1 from public.three_d_assets a where a.id=asset_id and a.publication_status=\'published\')'
 elif table in geometry_tables:condition='exists(select 1 from public.geometry_revisions g join public.three_d_assets a on a.id=g.asset_id where g.id=geometry_revision_id and a.publication_status=\'published\')'
 elif table in revision_tables:condition='exists(select 1 from public.digital_twin_configuration_revisions r where r.id=configuration_revision_id and r.publication_status=\'published\')'
 else:condition="(geometry_revision_id is not null and exists(select 1 from public.geometry_revisions g join public.three_d_assets a on a.id=g.asset_id where g.id=geometry_revision_id and a.publication_status='published')) or (configuration_revision_id is not null and exists(select 1 from public.digital_twin_configuration_revisions r where r.id=configuration_revision_id and r.publication_status='published'))"
 add(f'create policy twin_public_read on public.{table} for select to anon using({condition}); create policy twin_member_read on public.{table} for select to authenticated using(({condition}) or (select e34_private.has_role(\'reviewer\'))); create policy twin_staff_write on public.{table} for all to authenticated using((select e34_private.has_role(\'reviewer\'))) with check((select e34_private.has_role(\'reviewer\')));')
for table in ['reconstruction_jobs','reconstruction_evidence']:
 add(f"alter table public.{table} enable row level security; revoke all on public.{table} from public,anon,authenticated; grant select,insert,delete on public.{table} to authenticated; create policy twin_submission_read on public.{table} for select to authenticated using(user_id=(select auth.uid()) or (select e34_private.has_role('reviewer'))); create policy twin_submission_delete on public.{table} for delete to authenticated using(user_id=(select auth.uid()));")
 extra=" and status='needs-evidence'" if table=='reconstruction_jobs' else ''
 add(f"create policy twin_submission_create on public.{table} for insert to authenticated with check(user_id=(select auth.uid()){extra});")
add("grant update on public.reconstruction_jobs to authenticated; create policy twin_job_review on public.reconstruction_jobs for update to authenticated using((select e34_private.has_role('reviewer'))) with check((select e34_private.has_role('reviewer')));")
add('''alter table public.user_workshop_sessions enable row level security; revoke all on public.user_workshop_sessions from public,anon,authenticated; grant select,insert,update,delete on public.user_workshop_sessions to authenticated;
create policy twin_session_read on public.user_workshop_sessions for select to authenticated using(user_id=(select auth.uid()));
create policy twin_session_create on public.user_workshop_sessions for insert to authenticated with check(user_id=(select auth.uid()));
create policy twin_session_update on public.user_workshop_sessions for update to authenticated using(user_id=(select auth.uid())) with check(user_id=(select auth.uid()));
create policy twin_session_delete on public.user_workshop_sessions for delete to authenticated using(user_id=(select auth.uid()));''')
# Cover reference keys used by source joins and ownership checks.
indexes={'asset_sources':['source_id','license_id'],'three_d_assets':['source_id'],'geometry_revisions':['asset_id'],'digital_twin_vehicles':['model_id','source_id'],'digital_twin_configurations':['vehicle_id'],'digital_twin_configuration_revisions':['configuration_id'],'assembly_nodes':['part_id','geometry_revision_id'],'component_meshes':['geometry_revision_id','part_id'],'geometry_measurements':['geometry_revision_id'],'accuracy_reviews':['geometry_revision_id','configuration_revision_id','reviewer_id'],'reconstruction_jobs':['user_id','part_id'],'reconstruction_evidence':['job_id,user_id','user_id'],'user_workshop_sessions':['user_id','configuration_id','configuration_revision_id,configuration_id']}
for table in revision_tables:indexes.setdefault(table,[]).append('configuration_revision_id')
for table in ['assembly_relationships','fastener_connections','electrical_connections','fluid_connections']: indexes[table] += ['configuration_revision_id,from_node','configuration_revision_id,to_node']
indexes['mounting_points'] += ['configuration_revision_id,node_id']
indexes['removal_animations'] += ['configuration_revision_id,node_id']
indexes['disassembly_dependencies'] += ['configuration_revision_id,target_node','configuration_revision_id,prerequisite_node']
for table,fields in indexes.items():
 for i,field in enumerate(fields):add(f'create index twin_{table}_{i} on public.{table}({field});')
add('''create function e34_private.check_twin_publication() returns trigger language plpgsql security definer set search_path='' as $$
begin
 if new.publication_status='published' and not exists(select 1 from public.asset_sources s join public.asset_licenses l on l.id=s.license_id where s.id=new.source_id and l.redistribution='allowed') then raise exception 'A documented redistribution license is required before publishing an asset'; end if; return new;
end; $$;
revoke all on function e34_private.check_twin_publication() from public,anon,authenticated;
create trigger twin_asset_license_gate before insert or update on public.three_d_assets for each row execute function e34_private.check_twin_publication();''')
Path('database/digital-twin.sql').write_text('-- Metadata only: large geometry/source binaries are stored separately.\n'+'\n'.join(sql))
